(()=>{const nav=document.querySelector('nav'),toggle=document.querySelector('.mobile-menu-toggle'),links=document.querySelector('.navlinks');function close(){nav.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation')}toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';nav.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')});links.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));document.addEventListener('click',e=>{if(!nav.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('menu-open')){close();toggle.focus()}});matchMedia('(min-width:801px)').addEventListener('change',close);document.querySelector('.navcta').addEventListener('click',close)})();

// Highlight the section currently being viewed, including the sticky story.
(()=>{const links=[...document.querySelectorAll('#primary-nav a')],sections=links.map(a=>document.querySelector(a.getAttribute('href')));let queued=false;function select(index){links.forEach((a,i)=>{a.classList.toggle('is-active',i===index);if(i===index)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}function update(){queued=false;const line=document.querySelector('nav').getBoundingClientRect().bottom+Math.min(innerHeight*.2,160);let active=-1;sections.forEach((section,i)=>{const r=section.getBoundingClientRect();if(r.top<=line&&r.bottom>line)active=i});select(active)}function queue(){if(!queued){queued=true;requestAnimationFrame(update)}}links.forEach((a,i)=>a.addEventListener('click',()=>select(i)));addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);addEventListener('hashchange',queue);addEventListener('pageshow',queue);update()})();
